-- ESPELHO do estado aplicado em produção em 2026-08-11 (DB-as-source).
-- Documentação massiva do schema evo: 1.913 COMMENT ON (tabelas, colunas, funções, views).
-- Gerada pela auditoria orquestrada (6 levas). No-op se re-executada (COMMENT ON é idempotente).
-- 
COMMENT ON TABLE evo.evolution_conversations IS 'Tabela-mãe (parent) do particionamento de conversas; sem dados próprios — as partições reais são evolution_conversations_wpp2 (ativa, 15.5K linhas) e as por departamento (compras, default, financeiro, logistica, marketing, ~0 linhas).';
COMMENT ON TABLE evo.evolution_conversations_compras IS 'Partição de conversas do departamento de compras (aquisição de brindes promocionais); 0-2 linhas — departamento ainda sem volume real, operação vive na wpp2.';
COMMENT ON COLUMN evo.evolution_conversations_compras.id IS 'PK uuid interna. Use para JOINs. Não é ID do WhatsApp.';
COMMENT ON COLUMN evo.evolution_conversations_compras.contact_id IS 'FK → evo.evolution_contacts.id. Chave de JOIN para dados do contato.';
COMMENT ON COLUMN evo.evolution_conversations_compras.remote_jid IS 'JID primário do contato: "PHONE@s.whatsapp.net" (individuais) ou "GROUP@g.us" (grupos). UNIQUE com instance_name. ARMADILHA: pode conter "@lid".';
COMMENT ON COLUMN evo.evolution_conversations_compras.status IS 'Estado da conversa. Valores: aberta|arquivada (CHECK em português). Filtro padrão: WHERE status = ''aberta''.';
COMMENT ON COLUMN evo.evolution_conversations_compras.assigned_to IS 'UUID (como text) do agente responsável → zapp.profiles.id. 100% preenchido desde 2026-08-09; RLS depende dele.';
COMMENT ON COLUMN evo.evolution_conversations_compras.department IS 'Departamento de atendimento. Nesta partição: ''compras''. Valores possíveis: comercial|financeiro|logistica|compras|marketing.';
COMMENT ON COLUMN evo.evolution_conversations_compras.subject IS 'Assunto da conversa definido pelo agente para catalogação interna. NULL = sem assunto definido.';
COMMENT ON COLUMN evo.evolution_conversations_compras.priority IS 'Prioridade de atendimento. Valores: low|normal|high|urgent. Default ''normal''.';
COMMENT ON COLUMN evo.evolution_conversations_compras.labels IS 'Array de labels da conversa (tags visuais no CRM). Diferente das labels do WhatsApp em evolution_contacts. NULL = sem labels.';
COMMENT ON COLUMN evo.evolution_conversations_compras.message_count IS 'Total de mensagens na conversa (qualquer direção). Mantido por trigger/cron de reconciliação.';
COMMENT ON COLUMN evo.evolution_conversations_compras.first_message_at IS 'Timestamp da primeira mensagem desta conversa.';
COMMENT ON COLUMN evo.evolution_conversations_compras.last_message_at IS 'Timestamp da última mensagem (qualquer direção). Desnormalização para evitar JOIN em evolution_messages.';
COMMENT ON COLUMN evo.evolution_conversations_compras.last_inbound_at IS 'Timestamp da última mensagem recebida do contato (from_me=false). Para SLA de resposta: now() - last_inbound_at.';
COMMENT ON COLUMN evo.evolution_conversations_compras.last_outbound_at IS 'Timestamp da última mensagem enviada pela Promo. Para medir tempo de silêncio da empresa.';
COMMENT ON COLUMN evo.evolution_conversations_compras.first_response_at IS 'Timestamp da primeira resposta da Promo ao contato. Base para first_response_seconds. NULL = ainda sem resposta.';
COMMENT ON COLUMN evo.evolution_conversations_compras.first_response_seconds IS 'SLA de primeira resposta em segundos. NULL se ainda não respondida.';
COMMENT ON COLUMN evo.evolution_conversations_compras.resolution_at IS 'Timestamp em que a conversa foi resolvida (status → ''arquivada''). NULL = ainda aberta.';
COMMENT ON COLUMN evo.evolution_conversations_compras.resolution_seconds IS 'Tempo total de resolução em segundos (first_message_at → resolution_at). Métrica de SLA de resolução.';
COMMENT ON COLUMN evo.evolution_conversations_compras.is_bot_active IS 'true = chatbot gerenciando a conversa. Agentes devem verificar antes de intervir. Default false.';
COMMENT ON COLUMN evo.evolution_conversations_compras.bot_session_id IS 'ID da sessão do chatbot (Typebot, N8N ou interno). NULL se bot não ativo.';
COMMENT ON COLUMN evo.evolution_conversations_compras.satisfaction_score IS 'CSAT: 1 (muito insatisfeito) a 5 (muito satisfeito). NULL = não coletado.';
COMMENT ON COLUMN evo.evolution_conversations_compras.satisfaction_comment IS 'Comentário livre do CSAT, coletado junto com satisfaction_score após resolução. NULL = não coletado.';
COMMENT ON COLUMN evo.evolution_conversations_compras.instance_name IS 'Instância WhatsApp. Sempre "wpp2". Parte da chave natural (remote_jid, instance_name).';
COMMENT ON COLUMN evo.evolution_conversations_compras.metadata IS 'jsonb livre para dados extras (ex.: integração Bitrix24, dados de campanha). NULL = sem extras.';
COMMENT ON COLUMN evo.evolution_conversations_compras.created_at IS 'Timestamp de criação da conversa no banco. Próximo de first_message_at, mas pode divergir.';
COMMENT ON COLUMN evo.evolution_conversations_compras.updated_at IS 'Timestamp do último UPDATE. Mantido por trigger.';
COMMENT ON COLUMN evo.evolution_conversations_compras.last_message_content IS 'Preview da última mensagem (truncado). Desnormalização para listar sem JOIN em evolution_messages.';
COMMENT ON COLUMN evo.evolution_conversations_compras.last_message_type IS 'Tipo da última mensagem (text, image, audio, etc.). Desnormalização junto com last_message_content.';
COMMENT ON COLUMN evo.evolution_conversations_compras.unread_count IS 'Mensagens inbound não lidas pelo agente no CRM. Decrementado quando o agente abre a conversa. Default 0.';
