COMMENT ON COLUMN evo.evolution_conversations_marketing.instance_name IS 'Instância WhatsApp. Sempre "wpp2". Parte da chave natural (remote_jid, instance_name).';
COMMENT ON COLUMN evo.evolution_conversations_marketing.metadata IS 'jsonb livre para dados extras (ex.: integração Bitrix24, dados de campanha). NULL = sem extras.';
COMMENT ON COLUMN evo.evolution_conversations_marketing.created_at IS 'Timestamp de criação da conversa no banco. Próximo de first_message_at, mas pode divergir.';
COMMENT ON COLUMN evo.evolution_conversations_marketing.updated_at IS 'Timestamp do último UPDATE. Mantido por trigger.';
COMMENT ON COLUMN evo.evolution_conversations_marketing.last_message_content IS 'Preview da última mensagem (truncado). Desnormalização para listar sem JOIN em evolution_messages.';
COMMENT ON COLUMN evo.evolution_conversations_marketing.last_message_type IS 'Tipo da última mensagem (text, image, audio, etc.). Desnormalização junto com last_message_content.';
COMMENT ON COLUMN evo.evolution_conversations_marketing.unread_count IS 'Mensagens inbound não lidas pelo agente no CRM. Decrementado quando o agente abre a conversa. Default 0.';
COMMENT ON TABLE evo.evolution_message_queue IS 'Fila de envio de mensagens WhatsApp (agendamento, prioridade e retry). Planejada: 0 linhas com 4 índices criados — integração de envio ainda não populando.';
COMMENT ON COLUMN evo.evolution_message_queue.id IS 'PK uuid interna do item da fila.';
COMMENT ON COLUMN evo.evolution_message_queue.contact_id IS 'FK → evo.evolution_contacts.id do destinatário. NULL se o envio não é para contato cadastrado.';
COMMENT ON COLUMN evo.evolution_message_queue.remote_jid IS 'JID de destino: "PHONE@s.whatsapp.net" (individuais) ou "GROUP@g.us" (grupos). ARMADILHA: pode conter "@lid".';
COMMENT ON COLUMN evo.evolution_message_queue.message_type IS 'Tipo de mensagem a enviar: text|image|audio|video|document|sticker|buttons|template (vocabulário de evolution_messages).';
COMMENT ON COLUMN evo.evolution_message_queue.content IS 'Conteúdo de texto da mensagem. Para áudio/vídeo/imagem: vazio ou caption. Para stickers sem legenda: NULL. Truncado em 65535 chars.';
COMMENT ON COLUMN evo.evolution_message_queue.media_url IS 'URL da mídia a enviar (image/audio/video/document). NULL para texto puro.';
COMMENT ON COLUMN evo.evolution_message_queue.media_filename IS 'Nome original do arquivo de mídia para envio como documento. NULL = sem mídia.';
COMMENT ON COLUMN evo.evolution_message_queue.template_id IS 'FK → evo.evolution_message_templates.id quando envio usa template oficial. NULL = envio livre.';
COMMENT ON COLUMN evo.evolution_message_queue.template_vars IS 'jsonb com variáveis de interpolação do template (ex.: {"nome": "Maria"}). NULL = template sem variáveis.';
COMMENT ON COLUMN evo.evolution_message_queue.scheduled_at IS 'Momento agendado do envio. NULL = enviar imediatamente. Índice idx_msg_queue_scheduled cobre este campo.';
COMMENT ON COLUMN evo.evolution_message_queue.priority IS 'Prioridade de envio (maior = antes). Default 0.';
COMMENT ON COLUMN evo.evolution_message_queue.status IS 'Estado do item na fila. Valores previstos: pending|processing|sent|failed. Default pending.';
COMMENT ON COLUMN evo.evolution_message_queue.attempts IS 'Tentativas de envio já executadas. Incrementado a cada falha.';
COMMENT ON COLUMN evo.evolution_message_queue.max_attempts IS 'Limite de tentativas antes de marcar failed. NULL = sem limite (retry infinito).';
COMMENT ON COLUMN evo.evolution_message_queue.sent_at IS 'Timestamp do envio aceito pela Evolution API. NULL = ainda não enviado.';
COMMENT ON COLUMN evo.evolution_message_queue.delivered_at IS 'Timestamp do delivery ack (DELIVERY_ACK). NULL = sem confirmação de entrega.';
COMMENT ON COLUMN evo.evolution_message_queue.read_at IS 'Timestamp do read ack (READ). NULL = não lida.';
COMMENT ON COLUMN evo.evolution_message_queue.error_message IS 'Mensagem de erro da última tentativa falha. NULL = sem erro.';
COMMENT ON COLUMN evo.evolution_message_queue.whatsapp_message_id IS 'ID da mensagem no WhatsApp retornado pela Evolution API após envio. Usar para dedupe/rastreio.';
COMMENT ON COLUMN evo.evolution_message_queue.source IS 'Origem do item na fila. Ex.: manual|sistema|api|bot|campanha. NULL = origem não rastreada.';
COMMENT ON COLUMN evo.evolution_message_queue.source_id IS 'ID do registro de origem (ex.: campanha, automação). Permite rastrear o item de volta ao disparador. NULL = sem origem.';
COMMENT ON COLUMN evo.evolution_message_queue.instance_name IS 'Instância WhatsApp que enviará a mensagem. Sempre "wpp2".';
COMMENT ON COLUMN evo.evolution_message_queue.created_by IS 'UUID (como text) do agente que criou o item → zapp.profiles.id. NULL = criado por sistema/bot.';
COMMENT ON COLUMN evo.evolution_message_queue.metadata IS 'jsonb livre (ex.: contexto de campanha, flags de integração). NULL = sem extras.';
COMMENT ON COLUMN evo.evolution_message_queue.created_at IS 'Timestamp de criação do item na fila.';
COMMENT ON TABLE evo.evolution_messages_comercial_03 IS 'Partição SOLTA (NÃO é filha do parent evolution_messages) com 5 linhas e ~2K seq scans — suspeita de roteamento errado de instância comercial; investigar antes de usar.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.id IS 'PK uuid interna. Use para JOINs (media_loss_registry.message_uuid → aqui). Não é ID do WhatsApp.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.message_id IS 'ID da mensagem no WhatsApp. Chave natural: (message_id, instance_name). ARMADILHA: filtrar message_id NOT LIKE ''pg-cron-canary-%'' em métricas.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.remote_jid IS 'JID primário do contato: "PHONE@s.whatsapp.net" (individuais) ou "GROUP@g.us" (grupos). ARMADILHA: pode conter "@lid" — trigger trg_normalize_remote_jid corrige em INSERT/UPDATE.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.from_me IS 'true = mensagem enviada pela Promo (outbound). INVARIANTE: from_me = (direction = ''outbound'').';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.message_type IS 'Tipo da mensagem. 21 valores reais: text|image|audio|document|unknown|video|sticker|conversation|audioMessage|contact|imageMessage|documentMessage|location|reactionMessage|stickerMessage|secretEncryptedMessage|videoMessage|buttonsMessage|contactMessage|templateMessage|albumMessage. NÃO existe ''link''.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.content IS 'Conteúdo de texto da mensagem. Para áudio/vídeo/imagem: vazio ou caption. Para stickers sem legenda: NULL. Truncado em 65535 chars.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_url IS 'URL da mídia (CDN do WhatsApp). 93% NULL (maioria text). ARMADILHA: URLs expiram — persistir via media_bucket/media_path.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_mimetype IS 'MIME type real da mídia (ex.: application/pdf). Fonte confiável para classificar documentos.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.quoted_message_id IS 'message_id da mensagem citada (reply no WhatsApp). NULL = sem citação.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.is_starred IS 'true = mensagem marcada com estrela no WhatsApp.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.is_important IS 'true = mensagem marcada como importante.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.category IS 'Categoria de negócio atribuída (ex.: orcamento|pedido|pos-venda). NULL = não categorizada.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.sentiment IS 'Sentimento classificado (ex.: positivo|neutro|negativo). NULL = não analisado (feature de IA).';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.tags IS 'Array de tags internas do CRM. NULL = sem tags.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.notes IS 'Notas internas dos agentes sobre a mensagem. NULL = sem notas.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.follow_up_at IS 'Momento agendado para follow-up da mensagem. NULL = sem follow-up.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.follow_up_done IS 'true = follow-up concluído. Default false.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.payload IS 'Resumo do webhook da Evolution. ARMADILHA: na prática {} ou NULL — não confiar; usar colunas dedicadas.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.created_at IS 'Timestamp de criação/ingestão do registro no banco.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.contact_id IS 'FK → evo.evolution_contacts.id (97% preenchido na wpp2). NULL = contato não resolvido.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.conversation_id IS 'FK → evo.evolution_conversations.id (100% preenchido na wpp2).';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.direction IS 'Direção canônica: inbound|outbound. Garantido por trigger trg_enforce_direction.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.status IS 'ARMADILHA: dois formatos — UPPERCASE do webhook (READ, DELIVERY_ACK, SERVER_ACK, PENDING, ERROR, PLAYED) e lowercase do CRM (sent, delivered, read, failed). Normalizar com UPPER() antes de comparar.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.status_at IS 'Timestamp do último evento de status (envio/entrega/leitura).';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.caption IS 'Legenda da mídia. ARMADILHA: 100% NULL na wpp2 — não usar para classificar.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_filename IS 'Nome original do arquivo (ex.: "Orçamento - 107753.pdf"). Útil para extrair extensão real.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_size IS 'Tamanho do arquivo em bytes. NULL = mídia não baixada.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.sent_by_bot IS 'true = enviada pelo chatbot, não por humano.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.template_name IS 'Nome do template oficial usado no envio. NULL = envio livre.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.instance_name IS 'Instância WhatsApp. Sempre "wpp2". Parte da chave natural (message_id, instance_name).';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.push_name IS 'Nome de exibição do remetente no WhatsApp (denormalizado de evolution_contacts).';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_type IS 'Tipo de mídia (legado, pode divergir de message_type). Prefira message_type.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.raw_data IS 'Payload bruto da Evolution API. ARMADILHA: 100% NULL — SEMPRE. Não consultar.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.deleted_at IS 'Soft delete. ARMADILHA: filtrar deleted_at IS NULL em QUALQUER query de negócio.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.edited_at IS 'Timestamp de edição (evento messages.edited). Quase sempre NULL na prática.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.updated_at IS 'Timestamp do último UPDATE. Mantido por trigger.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_meta IS 'jsonb com metadados da mídia (dimensões, duração, etc.). NULL = sem mídia.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.audio_meme_id IS 'FK → tabela de memes de áudio (reuso interno de áudios). NULL = não é meme.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.sticker_id IS 'FK → tabela de stickers salvos (trigger trg_auto_save_sticker_wpp2). NULL = não é sticker salvo.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.link_preview IS 'Preview de link: estrutura só {"url": "..."} (sem título/thumbnail na prática). NULL = sem preview.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.is_read IS 'true = lida. Default false.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.reply_to_id IS 'UUID interno da mensagem citada (resolvido por cron; 100% NULL hoje). Prefira quoted_message_id.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_bucket IS 'Bucket do storage (whatsapp-media, audio-messages, stickers). NULL = mídia não persistida.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_path IS 'Caminho do objeto no bucket (storage.objects). NULL = mídia não persistida.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_sha256 IS 'Hash SHA-256 do arquivo para dedupe/segurança. NULL = não processado.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.media_status IS 'Estado do download/processamento da mídia. Valores: pending|processing|ready|failed|expired|unknown|permanently_lost.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.transcription_status IS 'Status da transcrição de áudio. Feature desativada (E-36) — valores previstos: pending|processing|done|failed; na prática NULL.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.transcription IS 'Texto transcrito do áudio. Feature desativada (E-36) — sempre NULL na prática.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.error_code IS 'Código de erro do envio. ARMADILHA: campo histórico fraco — 21K msgs failed sem erro preenchido.';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.error_reason IS 'Motivo do erro do envio. Campo histórico fraco (ver error_code).';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.retry_attempt IS 'Tentativa atual de reenvio (1.915 preenchidos na wpp2).';
COMMENT ON COLUMN evo.evolution_messages_comercial_03.retry_total IS 'Total de tentativas planejadas. ARMADILHA: 100% NULL — não usar.';
