COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.quoted_message_id IS 'message_id da mensagem citada (reply no WhatsApp). NULL = sem citação.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.is_starred IS 'true = mensagem marcada com estrela no WhatsApp.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.is_important IS 'true = mensagem marcada como importante.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.category IS 'Categoria de negócio atribuída (ex.: orcamento|pedido|pos-venda). NULL = não categorizada.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.sentiment IS 'Sentimento classificado (ex.: positivo|neutro|negativo). NULL = não analisado (feature de IA).';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.tags IS 'Array de tags internas do CRM. NULL = sem tags.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.notes IS 'Notas internas dos agentes sobre a mensagem. NULL = sem notas.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.follow_up_at IS 'Momento agendado para follow-up da mensagem. NULL = sem follow-up.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.follow_up_done IS 'true = follow-up concluído. Default false.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.payload IS 'Resumo do webhook da Evolution. ARMADILHA: na prática {} ou NULL — não confiar; usar colunas dedicadas.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.created_at IS 'Timestamp de criação/ingestão do registro no banco.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.contact_id IS 'FK → evo.evolution_contacts.id. NULL = contato não resolvido.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.conversation_id IS 'FK → evo.evolution_conversations.id.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.direction IS 'Direção canônica: inbound|outbound. Garantido por trigger trg_enforce_direction.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.status IS 'ARMADILHA: dois formatos — UPPERCASE do webhook (READ, DELIVERY_ACK, SERVER_ACK, PENDING, ERROR, PLAYED) e lowercase do CRM (sent, delivered, read, failed). Normalizar com UPPER() antes de comparar.';
COMMENT ON COLUMN evo.evolution_messages_wpp2_archive.status_at IS 'Timestamp do último evento de status (envio/entrega/leitura).';
COMMENT ON TABLE evo.evolution_reactions IS 'Reações (emoji) a mensagens, ingestão do evento messages.reaction da Evolution API. 113 linhas — sem FK para evolution_messages (integridade por contrato de ingestão).';
COMMENT ON TABLE evo._secure_config IS 'Configuracao sensivel do schema evo (chave-valor). Acesso restrito a service_role - nao expor via PostgREST/RLS; usada para parametros operacionais internos da Promo Brindes.';
COMMENT ON COLUMN evo._secure_config.key IS 'Chave unica da configuracao (identificador do parametro). Nao pode ser NULL.';
COMMENT ON COLUMN evo._secure_config.value IS 'Valor da configuracao em texto (JSON serializado quando estruturado). Pode ser NULL se a chave ainda nao possui valor definido.';
COMMENT ON COLUMN evo._secure_config.created_at IS 'Timestamp de criacao da linha. Definido no INSERT; nao e atualizado automaticamente.';
COMMENT ON TABLE evo._snapshot_version_state IS 'Tabela de 1 linha que versiona os snapshots de contatos: versao incrementada por triggers (trigger_snapshot_version_*) a cada mutacao em evolution_contacts; lida via get_snapshot_version/increment_snapshot_version.';
COMMENT ON COLUMN evo._snapshot_version_state.snapshot_id IS 'Identificador sequencial do snapshot vigente. Incrementado por triggers a cada mutacao relevante - nunca escrito pela aplicacao.';
COMMENT ON COLUMN evo._snapshot_version_state.current_version IS 'Versao corrente do snapshot (numero absoluto, monotonico). Usada por get_snapshot_version/validate_snapshot_freshness para detectar snapshots obsoletos.';
COMMENT ON COLUMN evo._snapshot_version_state.last_increment_at IS 'Timestamp do ultimo incremento de versao. NULL se nenhuma mutacao ocorreu desde a criacao da linha.';
COMMENT ON COLUMN evo._snapshot_version_state.table_affected IS 'Nome da tabela cuja mutacao gerou o ultimo incremento (ex.: evolution_contacts). Vocabulario livre, sem enum fixo. NULL se o incremento nao foi rastreado por tabela.';
COMMENT ON COLUMN evo._snapshot_version_state.operation_count IS 'Quantidade de operacoes (INSERT/UPDATE/DELETE) contabilizada no ultimo ciclo de incremento. ARMADILHA: escopo exato depende do trigger - nao usar como contador acumulado permanente.';
COMMENT ON TABLE evo.contact_id_graveyard IS 'Cemiterio de UUIDs de contatos deletados: impede reuso de IDs (trigger_prevent_contact_id_reuse bloqueia INSERT em evolution_contacts com id presente aqui). Populada por trigger_auto_graveyard_on_delete.';
COMMENT ON COLUMN evo.contact_id_graveyard.deleted_contact_id IS 'UUID do contato deletado (antigo evolution_contacts.id). Chave anti-reuso: tentativa de reinsert com este id e bloqueada por trigger.';
COMMENT ON COLUMN evo.contact_id_graveyard.original_remote_jid IS 'JID WhatsApp do contato no momento da exclusao (ex.: "5511999999999@s.whatsapp.net" ou "GRUPO@g.us"). NULL se nao capturado na exclusao.';
COMMENT ON COLUMN evo.contact_id_graveyard.deleted_at IS 'Timestamp da exclusao. Preenchido pelo trigger de graveyard na remocao do contato.';
COMMENT ON COLUMN evo.contact_id_graveyard.expiration_date IS 'Data em que o registro expira e o UUID fica liberado para reuso. Limpeza feita por cleanup_expired_contact_ids (rotina/cron). NULL = retencao indefinida.';
COMMENT ON COLUMN evo.contact_id_graveyard.reason IS 'Motivo da exclusao (vocabulario livre, ex.: manual, merge, limpeza). NULL se nao informado. Maximo 255 caracteres.';
COMMENT ON COLUMN evo.contact_id_graveyard.audit_user_id IS 'UUID do usuario/agente que executou a exclusao, para auditoria. NULL se a exclusao foi automatica (trigger/rotina).';
COMMENT ON TABLE evo.contact_identity IS 'Identidade unificada LID/PN de contatos: resolve JIDs "@lid" (bug Evolution 2.3.7) para numeros de telefone. ~12,6K linhas na Promo Brindes; mantida por trg_sync_contact_identity (a partir de lid_phone_map) e consultada via fn_resolve_identity.';
COMMENT ON COLUMN evo.contact_identity.id IS 'UUID da identidade (PK). Gerado na insercao; sem significado de negocio.';
COMMENT ON COLUMN evo.contact_identity.lid_jid IS 'JID LID do contato (formato "NUMERO@lid"). ARMADILHA: e o JID nao-resolvido que aparece em eventos/mensagens - use pn_jid/phone_number para o numero real.';
COMMENT ON COLUMN evo.contact_identity.pn_jid IS 'JID primario (PN) resolvido, formato "5511999999999@s.whatsapp.net". NULL enquanto a resolucao LID para PN nao foi confirmada.';
COMMENT ON COLUMN evo.contact_identity.phone_number IS 'Numero de telefone puro (sem sufixo @s.whatsapp.net), extraido do PN. NULL se a identidade ainda nao convergiu.';
COMMENT ON COLUMN evo.contact_identity.instance_name IS 'Nome da instancia Evolution a que pertence a identidade (ex.: "wpp2"). ARMADILHA: o mesmo numero pode ter identidades por instancia - filtrar por instance_name em consultas.';
COMMENT ON COLUMN evo.contact_identity.confidence IS 'Confianca da resolucao LID para PN. Vocabulario enum-like: high, medium, low, bootstrap_invalid. ARMADILHA: bootstrap_invalid indica mapeamento inicial invalido - nao tratar como numero definitivo.';
COMMENT ON COLUMN evo.contact_identity.source IS 'Origem do mapeamento (ex.: lid_phone_map, evento de mensagem, backfill). Vocabulario livre. NULL se nao registrada.';
COMMENT ON COLUMN evo.contact_identity.first_seen IS 'Primeira vez que o JID LID foi observado. NULL se nao rastreado.';
COMMENT ON COLUMN evo.contact_identity.last_seen IS 'Ultima vez que o JID LID foi observado em atividade. NULL se nunca visto ativo; util para poda de identidades obsoletas.';
COMMENT ON COLUMN evo.contact_identity.raw_signal IS 'Payload bruto (JSONB) do evento que originou a identidade (ex.: dados de webhook de presenca/mensagem). NULL se nao houve sinal capturado. ARMADILHA: formato nao contratado - usar com cautela.';
COMMENT ON TABLE evo.evolution_contact_rate_limits IS 'Controle de rate limit por contato (remote_jid): janelas de contagem de mensagens para prevencao de flood/ban da Promo Brindes. Sem linhas no momento (reltuples 0) - estrutura pronta para uso.';
COMMENT ON COLUMN evo.evolution_contact_rate_limits.id IS 'UUID do registro de rate limit (PK).';
COMMENT ON COLUMN evo.evolution_contact_rate_limits.remote_jid IS 'JID do contato limitado ("5511999999999@s.whatsapp.net" ou "GRUPO@g.us"). Chave natural da janela.';
COMMENT ON COLUMN evo.evolution_contact_rate_limits.message_count IS 'Quantidade de mensagens contabilizadas na janela atual. Zerado quando a janela reinicia.';
COMMENT ON COLUMN evo.evolution_contact_rate_limits.window_start IS 'Inicio da janela de contagem (janela fixa ou deslizante, conforme a rotina que mantem a tabela).';
COMMENT ON COLUMN evo.evolution_contact_rate_limits.is_rate_limited IS 'Flag: true = contato excedeu o limite e esta temporariamente limitado. ARMADILHA: valor derivado, recalculavel a partir de message_count vs limite configurado.';
COMMENT ON COLUMN evo.evolution_contact_rate_limits.created_at IS 'Timestamp de criacao do registro.';
COMMENT ON COLUMN evo.evolution_contact_rate_limits.updated_at IS 'Timestamp da ultima atualizacao (message_count/is_rate_limited). Mantido por trigger de updated_at.';
COMMENT ON COLUMN evo.evolution_contacts.presence_status IS 'Status de presenca do contato (vocabulario enum-like: online|offline|composing). Criada em 2026-08-11 (melhoria status de contato); mantida por fn_touch_contact_presence (throttle 60s anti hot-row). Dados dependem do evento presence.update da Evolution API - se a config nao envia, permanece NULL.';
COMMENT ON COLUMN evo.evolution_contacts.last_seen_at IS 'Ultima vez que o contato foi visto online. NULL se nunca observado. Mantido por fn_touch_contact_presence; populado quando presence.update chega (config Evolution pendente em 2026-08-11).';
COMMENT ON COLUMN evo.evolution_contacts.last_presence_at IS 'Timestamp do ultimo evento de presenca recebido (presence.update). Pode divergir de last_seen_at. Mantido por fn_touch_contact_presence com throttle de 60s.';
COMMENT ON COLUMN evo.evolution_contacts.is_on_whatsapp IS 'Flag: true se o numero esta ativo no WhatsApp. Verificado por fn_check_whatsapp_numbers (lote 50, usa evolution_whatsapp_check_queue). NULL = ainda nao verificado. Depende da auth da API Evolution (pendencia 2026-08-11).';
COMMENT ON COLUMN evo.evolution_contacts.whatsapp_checked_at IS 'Timestamp da ultima verificacao de is_on_whatsapp. NULL = nunca verificado.';
COMMENT ON TABLE evo.lid_convergence_history IS 'Historico de snapshots diarios de convergencia LID: numeros absolutos e delta de resolucao @lid para PN. Alimentado por rotina/cron diaria; base da view v_lid_convergence_status.';
COMMENT ON TABLE evo.media_download_queue IS 'Fila de download de mídia do WhatsApp: mensagens com mídia entram por trigger (trg_enqueue_media_wpp2) e são processadas por workers via rpc_claim_media_download_batch/rpc_complete_media_download; status: pending|processing|ready|failed|expired (na prática só done/failed/expired), com purge diária por fn_expire_old_media_queue.';
COMMENT ON TABLE evo.media_cleanup_log IS 'Log de limpeza de mídia (remoção de objetos do storage/expiração de URLs), escrito por crons e workers de manutenção; somente leitura para auditoria.';
COMMENT ON TABLE evo.media_scan_log IS 'Log de scans de segurança de mídia (validação/quarentena) executados pelo pipeline antes de liberar download; cada linha registra um scan e seu veredito (aprovado|rejeitado|quarentenado).';
COMMENT ON TABLE evo.media_storage_config IS 'Configuração do storage de mídia (bucket, endpoint, URL pública); ~1 linha ativa define o destino dos uploads dos workers (Supabase Storage → R2).';
COMMENT ON TABLE evo.media_cache IS 'Cache temporário de mídia mantido por fn_evict_media_cache e purgado pelo cron fn_purge_storage_cache(30); vazia/em desuso — não confiar dados aqui.';
COMMENT ON TABLE evo.media_dedupe_log IS 'Log de deduplicação de mídia: registra tentativas de download duplicadas (mesmo message_id/URL) e a decisão (reuso de objeto existente ou novo download); mantido pelo pipeline de download.';
COMMENT ON TABLE evo._media_url_backup IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot do mapeamento URL original → URL R2 (migração fn_migrate_media_urls_to_r2).';
COMMENT ON TABLE evo._backup_exf07_orphan_candidates IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Candidatos a órfãos do storage (EXF-07): objetos sem evolution_media correspondente.';
COMMENT ON TABLE evo._backup_exf07_ready_truncated IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Linhas de evolution_media com media_status=''ready'' truncadas no EXF-07.';
COMMENT ON TABLE evo._backup_fn_migrate IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Código fonte (prosrc) da função fn_migrate_media_urls_to_r2 antes de alteração.';
COMMENT ON TABLE evo._backup_fn_rpc_complete_media_download IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Código fonte (prosrc) da função rpc_complete_media_download antes de alteração.';
COMMENT ON TABLE evo._backup_gaps_20260810_category IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Linhas com gap de categoria ajustadas no fix de gaps de 2026-08-10.';
COMMENT ON TABLE evo._backup_gaps_20260810_e32 IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot das linhas alteradas pelo fix do gap E-32 (edited_at).';
COMMENT ON TABLE evo._backup_gaps_20260810_e34 IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot das linhas alteradas pelo fix do gap E-34 (link_preview).';
COMMENT ON TABLE evo._backup_gaps_20260810_e35 IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot das linhas alteradas pelo fix do gap E-35 (sticker/media_url).';
COMMENT ON TABLE evo._backup_gaps_20260810_fsize IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot das linhas alteradas pelo fix do gap de file_size (E-fsize).';
COMMENT ON TABLE evo._backup_gaps_20260810_lid IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot das linhas alteradas pelo fix do gap LID (remote_jid).';
COMMENT ON TABLE evo._backup_gaps_20260810_sha IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot das linhas alteradas pelo fix do gap de file_sha256.';
COMMENT ON TABLE evo._backup_links_r2_20260810 IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot de evolution_media antes da migração dos links para R2 (fn_migrate_media_urls_to_r2).';
COMMENT ON TABLE evo._backup_policies_20260810 IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot das policies RLS do schema evo antes de alteração.';
COMMENT ON TABLE evo._backup_w05_media_url IS 'BACKUP manual 2026-08-10 — não usar; aguardando arquivamento. Snapshot de media_url/media_status das mensagens W05 antes de expiração/limpeza.';
COMMENT ON COLUMN evo._backup_exf07_orphan_candidates.bucket_id IS 'Bucket do objeto órfão no storage (ex.: whatsapp-media); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_orphan_candidates.object_name IS 'Caminho/chave do objeto órfão em storage.objects; usado para localizar o blob; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_orphan_candidates.message_id IS 'message_id da mensagem associada ao objeto (pode ser NULL se não resolvido); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_orphan_candidates.instance_name IS 'Instância WhatsApp (ex.: wpp2); compõe a chave de resolução com message_id; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_orphan_candidates.remote_jid IS 'JID do contato (PHONE@s.whatsapp.net); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_orphan_candidates.message_type IS 'Tipo da mensagem (image|video|audio|document|sticker|...); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_orphan_candidates.mimetype IS 'MIME type do objeto (ex.: image/jpeg); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_orphan_candidates.size_bytes IS 'Tamanho do objeto em bytes; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_orphan_candidates.object_created_at IS 'Data de criação do objeto no storage; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.id IS 'PK original em evolution_media (gen_random_uuid); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.message_id IS 'ID da mensagem WhatsApp dona da mídia (UNIQUE na origem); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.remote_jid IS 'JID do contato (PHONE@s.whatsapp.net); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.media_type IS 'Tipo de mídia (image|audio|video|document|sticker); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.mime_type IS 'MIME type — na origem 98,7% NULL; preferir evolution_messages_wpp2.media_mimetype; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.file_name IS 'Nome do arquivo original; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.file_size IS 'Tamanho do arquivo em bytes; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.file_sha256 IS 'Hash SHA-256 do arquivo (dedupe/integridade); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.storage_path IS 'Caminho do objeto no bucket; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.storage_url IS 'URL pública/assinada do objeto (R2 pós-migração); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.base64_data IS 'Conteúdo base64 da mídia quando armazenado inline (pesado); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.caption IS 'Legenda da mídia (ex.: imagem com legenda); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.duration_seconds IS 'Duração em segundos (áudio/vídeo); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.width IS 'Largura em pixels (imagem/vídeo); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.height IS 'Altura em pixels (imagem/vídeo); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.is_animated IS 'true = mídia animada (GIF/sticker animado); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.thumbnail_base64 IS 'Thumbnail em base64 (na prática sempre vazia); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.created_at IS 'Data de criação do registro em evolution_media; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.storage_bucket IS 'Bucket do objeto (ex.: whatsapp-media, audio-messages); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.storage_path_clean IS 'storage_path normalizado/sem prefixo legado; congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.media_status IS 'Status da mídia na origem: pending|processing|ready|failed|expired|unknown|permanently_lost; neste backup só ''ready''; congelado.';
COMMENT ON COLUMN evo._backup_exf07_ready_truncated.instance_name IS 'Instância WhatsApp (ex.: wpp2); congelado no backup EXF-07.';
COMMENT ON COLUMN evo._backup_fn_migrate.prosrc IS 'Corpo (source) da função fn_migrate_media_urls_to_r2 antes da alteração de 2026-08-10; congelado no backup.';
COMMENT ON COLUMN evo._backup_fn_migrate._row_id IS 'Sequencial interno do backup (ordem de captura); sem significado de negócio.';
COMMENT ON COLUMN evo._backup_fn_rpc_complete_media_download.proname IS 'Nome da função (rpc_complete_media_download); congelado no backup.';
COMMENT ON COLUMN evo._backup_fn_rpc_complete_media_download.args IS 'Assinatura de argumentos da função (serializada de pg_proc); congelado no backup.';
COMMENT ON COLUMN evo._backup_fn_rpc_complete_media_download.prosrc IS 'Corpo (source) da função rpc_complete_media_download antes da alteração; congelado no backup.';
COMMENT ON COLUMN evo._backup_fn_rpc_complete_media_download._row_id IS 'Sequencial interno do backup; sem significado de negócio.';
COMMENT ON COLUMN evo._backup_gaps_20260810_category.id IS 'PK da linha original ajustada (gap de categoria); congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_category.category IS 'Valor da categoria antes do fix de 2026-08-10; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_e32.id IS 'PK da linha original em evolution_messages_wpp2; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_e32.message_id IS 'ID da mensagem WhatsApp afetada pelo gap E-32 (edited_at); congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_e32.edited_at IS 'Valor original de edited_at antes do fix E-32; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_e34.id IS 'PK da linha original; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_e34.link_preview IS 'link_preview original ({url: ...}) antes do fix E-34; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_e35.id IS 'PK da linha original; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_e35.sticker_id IS 'sticker_id original antes do fix E-35; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_e35.media_url IS 'media_url original antes do fix E-35; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_fsize.id IS 'PK da linha original; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_fsize.file_size IS 'file_size original (gap de tamanho) antes do fix; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_fsize.storage_bucket IS 'storage_bucket original antes do fix de file_size; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_fsize.storage_path_clean IS 'storage_path_clean original antes do fix de file_size; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_lid.id IS 'PK da linha original; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_lid.remote_jid IS 'remote_jid original (contaminação @lid) antes do fix; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_sha.id IS 'PK da linha original; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_sha.message_id IS 'ID da mensagem com gap de file_sha256; congelado no backup.';
COMMENT ON COLUMN evo._backup_gaps_20260810_sha.file_sha256 IS 'file_sha256 original antes do fix; congelado no backup.';
COMMENT ON COLUMN evo._backup_links_r2_20260810.id IS 'PK original em evolution_media (gen_random_uuid); congelado no backup da migração R2.';
COMMENT ON COLUMN evo._backup_links_r2_20260810.message_id IS 'ID da mensagem WhatsApp dona da mídia (UNIQUE na origem); congelado no backup da migração R2.';
COMMENT ON COLUMN evo._backup_links_r2_20260810.remote_jid IS 'JID do contato (PHONE@s.whatsapp.net); congelado no backup da migração R2.';
