-- AGENTE-04 (gerado pelo orquestrador — agente original travou)
COMMENT ON TABLE evo.evolution_webhook_events_v2 IS 'Partição mensal de eventos normalizados do webhook Evolution. Tabela-mãe PARTICIONADA (dados vivem nas partições mensais _YYYY_MM; parent tem 0 linhas). Estrutura idêntica ao parent evolution_webhook_events_v2. SEMPRE filtrar por created_at — queries no parent varrem 13 partições.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.id IS 'PK uuid. Chave de JOIN com DLQ (original_event_id) e logs.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.event_type IS 'Tipo do evento Evolution (ex.: messages.upsert, messages.update, presence.update). Vocabulário livre — consultar valores via GROUP BY.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.instance_name IS 'Instância WhatsApp que originou o evento (ex.: "wpp2").';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.remote_jid IS 'JID do contato/grupo envolvido ("PHONE@s.whatsapp.net", "GROUP@g.us"). NULL para eventos sem destinatário (ex.: heartbeats).';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.from_me IS 'true = evento de mensagem enviada pela Promo; false = recebida. NULL para eventos sem direção (heartbeats, presença).';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.message_type IS 'Tipo de mensagem (text, image, audio, document...). NULL para eventos não-mensagem.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.push_name IS 'Nome de exibição do remetente no momento do evento. NULL se não informado.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.payload IS 'jsonb NORMALIZADO (NÃO é o raw da Evolution API). Chaves: content, fromMe, messageId, messageType, remoteJid, sync_source, sync_ts. NÃO tem ''event'' nem ''data.message.*''. Filtrar heartbeats: payload->>''heartbeat'' IS NULL.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.processed IS 'true = já processado pelo pipeline. Legacy: usado pela view active_webhook_events (processed AND status em processed/success).';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.processed_at IS 'Timestamp do processamento. NULL = não processado.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.error_message IS 'Erro do processamento. NULL = sem erro.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.status IS 'Estado: pending|processing|processed|failed|dead_letter (CHECK). View active_webhook_events normaliza para success|pending|failed.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.retry_count IS 'Número de tentativas de processamento. 0 = nunca retentado.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.created_at IS 'Timestamp de inserção do evento. USAR SEMPRE em filtros — o parent sem filtro varre 13 partições.';
COMMENT ON COLUMN evo.evolution_webhook_events_v2.source IS 'Rota de entrega: webhook-direct | rabbit-consumer | NULL (legado pré-20260808).';
