COMMENT ON TABLE evo.evolution_webhook_dlq IS 'Dead Letter Queue dos eventos do pipeline WhatsApp: eventos que falharam após esgotar retries. Monitorada por crons (fn_detect_ack_loss_gap) e views (v_ack_loss_candidates, v_evolution_dlq_open).';
COMMENT ON COLUMN evo.evolution_webhook_dlq.id IS 'PK uuid do registro de dead letter.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.original_event_id IS 'ID do evento original (evolution_webhook_events_v2.id) que falhou. NULL se o evento nunca entrou na v2.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.event_type IS 'Tipo do evento que falhou (messages.upsert, messages.update, send.message, message.ack...).';
COMMENT ON COLUMN evo.evolution_webhook_dlq.instance_name IS 'Instância WhatsApp do evento.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.remote_jid IS 'JID do contato/grupo envolvido. NULL se não disponível.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.payload IS 'jsonb do payload que falhou (pode ser o normalizado ou o envelope, conforme a rota).';
COMMENT ON COLUMN evo.evolution_webhook_dlq.error_message IS 'Mensagem de erro que levou à dead letter.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.error_stack IS 'Stack trace / detalhe do erro. NULL se não capturado.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.retry_count IS 'Tentativas já realizadas.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.max_retries IS 'Limite de tentativas antes de dead letter definitiva.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.next_retry_at IS 'Próximo horário de retry (índice parcial de pending/retrying). NULL = sem retry agendado.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.status IS 'Estado: pending|retrying|dead_letter|resolved (CHECK). View v_ack_loss_candidates classifica falhas.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.resolved_at IS 'Quando foi resolvido/reprocessado com sucesso. NULL = aberto.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.resolved_by IS 'Quem resolveu (agente, cron ou sistema).';
COMMENT ON COLUMN evo.evolution_webhook_dlq.created_at IS 'Timestamp de entrada na DLQ.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.last_request_id IS 'ID da última requisição pg_net/HTTP relacionada. NULL se não aplicável.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.raw_payload IS 'Payload bruto original (texto) quando o jsonb normalizado não bastar. NULL = não capturado.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.consumer_version IS 'Versão do consumer/edge function que gerou a DLQ. Útil para diagnóstico de deploy.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.queue_name IS 'Nome da fila RabbitMQ de origem. NULL para rota webhook direto.';
COMMENT ON COLUMN evo.evolution_webhook_dlq.source_event_id IS 'ID de origem para dedupe (UNIQUE parcial). NULL se não aplicável.';
COMMENT ON TABLE evo.evolution_notification_config IS 'Configuração de canais de notificação (email, slack, webhook). Criada/ampliada em 2026-08-11 (melhoria notificações).';
COMMENT ON COLUMN evo.evolution_notification_config.id IS 'PK uuid.';
COMMENT ON COLUMN evo.evolution_notification_config.channel IS 'Canal: email|slack|webhook|whatsapp_promo|in_app.';
COMMENT ON COLUMN evo.evolution_notification_config.webhook_url IS 'URL do webhook para o canal webhook. NULL se outro canal.';
COMMENT ON COLUMN evo.evolution_notification_config.api_token IS 'Token da API do canal. SENSÍVEL — não logar.';
COMMENT ON COLUMN evo.evolution_notification_config.chat_id IS 'ID do chat/conversa destino (ex.: Slack channel). NULL se não aplicável.';
COMMENT ON COLUMN evo.evolution_notification_config.enabled IS 'true = canal ativo para envio.';
COMMENT ON COLUMN evo.evolution_notification_config.notify_on IS 'Array de tipos de evento que disparam notificação.';
COMMENT ON COLUMN evo.evolution_notification_config.created_at IS 'Timestamp de criação.';
COMMENT ON COLUMN evo.evolution_notification_config.updated_at IS 'Timestamp do último UPDATE.';
COMMENT ON COLUMN evo.evolution_notification_config.slack_webhook IS 'Webhook Slack específico (legado/alternativo a webhook_url). NULL se não usado.';
COMMENT ON COLUMN evo.evolution_notification_config.email_addresses IS 'Array de e-mails destino para canal email.';
COMMENT ON COLUMN evo.evolution_notification_config.notify_on_hours IS 'Janela de horas em que notificar (formato texto). NULL = 24h.';
COMMENT ON COLUMN evo.evolution_notification_config.notify_on_days IS 'Array de dias da semana (0-6) em que notificar. NULL = todos.';
COMMENT ON COLUMN evo.evolution_notification_config.priority_filter IS 'Filtro de prioridade mínima (array de severidades). NULL = todas.';
COMMENT ON TABLE evo.evolution_notification_log IS 'Log de envio de notificações (um registro por envio tentado).';
COMMENT ON COLUMN evo.evolution_notification_log.id IS 'PK uuid.';
COMMENT ON COLUMN evo.evolution_notification_log.channel IS 'Canal usado no envio.';
COMMENT ON COLUMN evo.evolution_notification_log.alert_id IS 'FK lógica para o alerta que gerou a notificação (evolution_alerts.id). NULL se não originado de alerta.';
COMMENT ON COLUMN evo.evolution_notification_log.message IS 'Texto da mensagem enviada.';
COMMENT ON COLUMN evo.evolution_notification_log.status IS 'Resultado do envio: sent|failed|delivered (vocabulário livre — verificar via GROUP BY).';
COMMENT ON COLUMN evo.evolution_notification_log.error_message IS 'Erro do envio. NULL = sucesso.';
COMMENT ON COLUMN evo.evolution_notification_log.sent_at IS 'Timestamp do envio.';
COMMENT ON COLUMN evo.evolution_notification_log.created_at IS 'Timestamp de criação do log.';
COMMENT ON TABLE evo.evolution_notification_outbox IS 'Outbox de notificações para canais EXTERNOS (email/slack/webhook/whatsapp_promo) — criada em 2026-08-11 (melhoria notificações). Consumida por dispatcher externo; zapp.fn_process_evolution_notifications grava aqui quando o canal é externo.';
COMMENT ON COLUMN evo.evolution_notification_outbox.id IS 'PK bigserial.';
COMMENT ON COLUMN evo.evolution_notification_outbox.notification_id IS 'FK → evolution_notifications.id (ON DELETE CASCADE).';
COMMENT ON COLUMN evo.evolution_notification_outbox.channel IS 'Canal externo destino.';
COMMENT ON COLUMN evo.evolution_notification_outbox.payload IS 'jsonb com o payload para o dispatcher externo.';
COMMENT ON COLUMN evo.evolution_notification_outbox.status IS 'Estado: pending|pending_external|sent|failed (vocabulário da melhoria 2026-08-11).';
COMMENT ON COLUMN evo.evolution_notification_outbox.created_at IS 'Timestamp de criação na outbox.';
COMMENT ON TABLE evo.evolution_fallback_events IS 'Eventos que caíram no caminho de FALLBACK (rota alternativa quando o processamento primário falhou). RLS: service_role ALL; authenticated só admin/supervisor.';
COMMENT ON COLUMN evo.evolution_fallback_events.id IS 'PK uuid.';
COMMENT ON COLUMN evo.evolution_fallback_events.instance_name IS 'Instância WhatsApp do evento.';
COMMENT ON COLUMN evo.evolution_fallback_events.event_type IS 'Tipo do evento.';
COMMENT ON COLUMN evo.evolution_fallback_events.payload IS 'jsonb com o payload do evento.';
COMMENT ON COLUMN evo.evolution_fallback_events.error_message IS 'Erro que levou ao fallback. NULL = sem erro.';
COMMENT ON COLUMN evo.evolution_fallback_events.created_at IS 'Timestamp de recebimento.';
COMMENT ON COLUMN evo.evolution_fallback_events.action IS 'Ação tomada no fallback (ex.: reprocessar, descartar).';
COMMENT ON COLUMN evo.evolution_fallback_events.instance IS 'Alias de instância (campo do envelope original). Pode divergir de instance_name.';
COMMENT ON COLUMN evo.evolution_fallback_events.ts IS 'Timestamp original do evento (do envelope).';
COMMENT ON TABLE evo.evolution_rabbit_consumer_stats IS 'Estatísticas coletadas dos consumers RabbitMQ (uma linha por réplica/coleta). Consumida via FDW pela view v_evolution_pipeline_health.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.id IS 'PK bigserial.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.collected_at IS 'Timestamp da coleta.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.instance IS 'Instância/consumer reportado.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.ok_count IS 'Eventos processados com sucesso (contador cumulativo do período da coleta).';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.retry_count IS 'Eventos retentados.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.drop_count IS 'Eventos descartados.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.drop_by IS 'jsonb com distribuição de drops por motivo.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.filas_ok IS 'Nome das filas saudáveis (texto concatenado).';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.replica IS 'Identificador da réplica do consumer (ex.: consumer.1, consumer.2).';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.ok IS 'Contador ok da última janela.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.shadow IS 'Contador de eventos shadow (espelho).';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.retry IS 'Contador de retries da última janela.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.drop IS 'Contador de drops da última janela.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.err IS 'Contador de erros da última janela.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.pg_log_ok IS 'Eventos confirmados no log do Postgres com sucesso.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.pg_log_err IS 'Falhas ao logar no Postgres.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.sentry_sent IS 'Eventos enviados ao Sentry.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.resub IS 'Re-subscrições/reconexões.';
COMMENT ON COLUMN evo.evolution_rabbit_consumer_stats.retry_by IS 'jsonb com distribuição de retries por motivo.';
COMMENT ON TABLE evo.evolution_source_schema_map IS 'Mapa de schemas/tabelas/colunas de FONTES externas descobertas (para auditoria de espelhamento). Planejada — sem linhas em 2026-08.';
COMMENT ON COLUMN evo.evolution_source_schema_map.id IS 'PK bigserial.';
COMMENT ON COLUMN evo.evolution_source_schema_map.database_name IS 'Nome do banco de origem.';
COMMENT ON COLUMN evo.evolution_source_schema_map.schema_name IS 'Schema de origem.';
COMMENT ON COLUMN evo.evolution_source_schema_map.table_name IS 'Tabela de origem.';
COMMENT ON COLUMN evo.evolution_source_schema_map.column_name IS 'Coluna de origem.';
COMMENT ON COLUMN evo.evolution_source_schema_map.data_type IS 'Tipo de dado na origem.';
COMMENT ON COLUMN evo.evolution_source_schema_map.is_nullable IS 'Nullable na origem (YES/NO).';
COMMENT ON COLUMN evo.evolution_source_schema_map.ordinal_position IS 'Posição ordinal na origem.';
COMMENT ON COLUMN evo.evolution_source_schema_map.is_primary_key IS 'true se coluna é PK na origem.';
COMMENT ON COLUMN evo.evolution_source_schema_map.is_unique IS 'true se coluna tem unique na origem.';
COMMENT ON COLUMN evo.evolution_source_schema_map.row_count_est IS 'Estimativa de linhas da tabela de origem.';
COMMENT ON COLUMN evo.evolution_source_schema_map.discovered_at IS 'Quando foi descoberta.';
COMMENT ON COLUMN evo.evolution_source_schema_map.raw_metadata IS 'jsonb com metadados brutos da descoberta.';
COMMENT ON TABLE evo.evolution_source_shadow_log IS 'Log de medições shadow entre fonte e espelho (auditoria de paridade de dados).';
COMMENT ON COLUMN evo.evolution_source_shadow_log.id IS 'PK uuid.';
COMMENT ON COLUMN evo.evolution_source_shadow_log.snapshot_date IS 'Data do snapshot.';
COMMENT ON COLUMN evo.evolution_source_shadow_log.window_days IS 'Janela em dias da medição.';
COMMENT ON COLUMN evo.evolution_source_shadow_log.source IS 'Fonte medida.';
COMMENT ON COLUMN evo.evolution_source_shadow_log.event_count IS 'Total de eventos na janela.';
COMMENT ON COLUMN evo.evolution_source_shadow_log.event_types IS 'jsonb com distribuição por tipo de evento.';
COMMENT ON COLUMN evo.evolution_source_shadow_log.dedup_rate IS 'Taxa de deduplicação (0-100).';
COMMENT ON COLUMN evo.evolution_source_shadow_log.captured_at IS 'Timestamp da captura.';
COMMENT ON TABLE evo.migration_watermark IS 'Marca d''água de migrações de dados (progresso de backfills por migração).';
COMMENT ON COLUMN evo.migration_watermark.migration_name IS 'Nome da migração.';
COMMENT ON COLUMN evo.migration_watermark.last_created_at IS 'Último created_at processado.';
COMMENT ON COLUMN evo.migration_watermark.last_id IS 'Último ID processado.';
COMMENT ON COLUMN evo.migration_watermark.rows_migrated IS 'Linhas migradas até agora.';
COMMENT ON COLUMN evo.migration_watermark.updated_at IS 'Timestamp da última atualização do watermark.';
COMMENT ON TABLE evo.evolution_deals IS 'Oportunidades de venda do funil comercial (lead → proposta → negociação → ganho/perdido) da Promo Brindes; registro central do CRM de vendas via WhatsApp. Status segue vocabulário fixo do funil; mantido pelo app e automações. ARMADILHA: deal é a oportunidade; a etiqueta visual do chat fica em evolution_labels.';
COMMENT ON TABLE evo.evolution_tasks IS 'Tarefas operacionais do time comercial (follow-up, envio de orçamento, cobrança). Status segue vocabulário tipo pending/in_progress/done; due_at NULL significa sem prazo definido. Mantida pelos vendedores via app.';
COMMENT ON TABLE evo.evolution_followup_rules IS 'Regras de follow-up automático: definem quando e como reabordar lead/deal sem resposta no WhatsApp (ex.: reenviar proposta após X dias). Avaliadas por automação agendada. ARMADILHA: regra mal calibrada gera spam e queima reputação do número.';
COMMENT ON TABLE evo.evolution_followups IS 'Execuções de follow-up disparadas pelas evolution_followup_rules; registra lead, regra, canal e resultado do contato. PLANEJADA (0 linhas em 2026-08); mantida por automação agendada.';
COMMENT ON TABLE evo.evolution_sales_pipeline IS 'Etapas do funil de vendas configuráveis (novo lead, proposta enviada, negociação, ganho/perdido). PLANEJADA (0 linhas em 2026-08); sem pipeline populado, deals ficam sem estágio canônico. Mantida por admin.';
COMMENT ON TABLE evo.evolution_stage_mapping IS 'Mapeia estágios do funil de vendas para labels do WhatsApp, refletindo a etapa do deal direto no chat. ARMADILHA: label sem mapeamento aqui não acompanha o estágio real do deal.';
COMMENT ON TABLE evo.evolution_sentiment_analysis IS 'Análise de sentimento de mensagens de clientes (positivo/neutro/negativo) para priorizar atendimento. PLANEJADA (0 linhas em 2026-08); mantida por automação/IA.';
COMMENT ON TABLE evo.evolution_labels IS 'Etiquetas visuais de chat no WhatsApp (ex.: Cliente quente, Aguardando resposta); vocabulário definido pelo admin e usado pelo funil via evolution_stage_mapping.';
COMMENT ON TABLE evo.evolution_label_associations IS 'Associação N:N entre chats/contatos e labels do WhatsApp. PLANEJADA (0 linhas em 2026-08); mantida por automação quando o estágio do deal muda.';
COMMENT ON TABLE evo.evolution_tags IS 'Tags internas de segmentação comercial (ex.: brinde corporativo, atacado, evento). Diferem de labels: tags são internas do CRM; labels são visíveis no WhatsApp.';
COMMENT ON TABLE evo.evolution_tag_assignments IS 'Vínculo N:N entre contatos/deals e tags de segmentação. PLANEJADA (0 linhas em 2026-08); mantida pelo app.';
COMMENT ON TABLE evo.evolution_quick_replies IS 'Respostas rápidas do time comercial para agilizar o atendimento (tabela de preços, prazos de produção, condições). Texto curto reutilizável no WhatsApp.';
COMMENT ON TABLE evo.evolution_message_templates IS 'Templates HSM da Meta (mensagens aprovadas para envio fora da janela de 24h). PLANEJADA (0 linhas em 2026-08). ARMADILHA: somente templates aprovados pela Meta podem ser enviados; variáveis devem casar com o payload.';
COMMENT ON TABLE evo.evolution_template_usage IS 'Histórico de uso de templates HSM (quem enviou, para qual contato, status). PLANEJADA (0 linhas em 2026-08); mantida pela automação de envio.';
COMMENT ON TABLE evo.evolution_keyword_automations IS 'Automações disparadas por palavra-chave recebida no WhatsApp (ex.: preço → envia tabela de valores). PLANEJADA (0 linhas em 2026-08); mantida por automação de entrada.';
COMMENT ON TABLE evo.evolution_scheduled_messages IS 'Mensagens agendadas para envio futuro (lembrete de follow-up, cobrança, campanha). PLANEJADA (0 linhas em 2026-08); mantida por scheduler.';
COMMENT ON TABLE evo.evolution_send_idempotency IS 'Chaves de idempotência de envio: garante que retentativas não dupliquem mensagens. PLANEJADA (0 linhas em 2026-08). ARMADILHA: limpar registros durante campanha ativa pode causar reenvio duplicado.';
COMMENT ON TABLE evo.evolution_api_consumers IS 'Consumidores de API autorizados a integrar com o CRM (chaves e escopos). Mantida por admin; revogar acesso remove a integração.';
COMMENT ON TABLE evo.evolution_business_hours IS 'Horário comercial da empresa (ex.: seg-sex 8h-18h) que regula janela de atendimento, follow-ups e envio de mensagens. Mantida por admin.';
COMMENT ON TABLE evo.evolution_holidays IS 'Feriados que suspendem automações e follow-ups fora do horário comercial. Mantida por admin.';
COMMENT ON TABLE evo.evolution_spam_keywords IS 'Palavras-chave que classificam mensagens recebidas como spam para filtro do atendimento. Mantida por admin.';
COMMENT ON TABLE evo.evolution_chatbot_responses IS 'Respostas do chatbot para atendimento inicial automático no WhatsApp (saudação, captura de intenção). Mantida por admin; integra com keyword_automations.';
COMMENT ON TABLE evo.evolution_automation_logs IS 'Log de execução de automações (follow-ups, keywords, agendamentos, templates). PLANEJADA (0 linhas em 2026-08); escrita por automação.';
COMMENT ON TABLE evo.evolution_bitrix_queue IS 'Fila de sincronização com Bitrix24: operações pendentes (criar/atualizar deal, contato, atividade) aguardando envio ao CRM externo. Mantida pelo worker de sync. ARMADILHA: itens presos indicam falha de integração com Bitrix24.';
COMMENT ON TABLE evo.evolution_settings IS 'Configurações gerais do módulo CRM/atendimento (chave-valor: ex. empresa, fuso, limites). Mantida por admin.';
COMMENT ON TABLE evo.evolution_groups IS 'Catalogo canonico de grupos de WhatsApp gerenciados. ATIVA desde 2026-08-11 (melhoria grupos): populada por fn_upsert_group_from_event (eventos) e fn_sync_groups_from_api (backfill, cron 464). ANTES disso ficava vazia - nao assumir dados historicos.';
COMMENT ON TABLE evo.evolution_group_participants IS 'Participantes dos grupos de WhatsApp. ATIVA desde 2026-08-11 (melhoria grupos): mantida por fn_upsert_group_participants (add/remove/promote/demote idempotente).';
COMMENT ON TABLE evo.evolution_group_messages IS 'Mensagens trocadas dentro dos grupos gerenciados. PLANEJADA (0 linhas em 2026-08); escrita pela automação de captura.';
COMMENT ON TABLE evo.evolution_group_rules IS 'Regras de automação para grupos (saudação de boas-vindas, anti-spam, resposta a comandos). PLANEJADA (0 linhas em 2026-08); mantida por admin.';
COMMENT ON TABLE evo.evolution_calls IS 'Registro de chamadas de voz (WhatsApp/telefone) com número, duração e resultado. ARMADILHA: resultado pode ficar NULL quando a chamada não é atendida; duração 0 indica chamada perdida.';
COMMENT ON TABLE evo.evolution_whatsapp_check_queue IS 'Fila de verificação de números WhatsApp (validade/status do número) antes de campanhas. Mantida por worker; remove números inválidos da lista de envio.';
-- AGENTE-05b colunas de negocio (gerado pelo orquestrador, complemento do agente_05)
