-- =============================================================================
-- AGENTE-08: Views internas, evolution_instance_credentials, evolution_mirror_*
-- Schema: evo | PostgreSQL 15.8 | Pipeline WhatsApp Promo Brindes
-- Somente COMMENT ON VIEW / TABLE / COLUMN — nenhum outro DDL
-- =============================================================================

-- ---------------------------------------------------------------------------
-- PARTE A — Views internas do schema evo (COMMENT ON VIEW)
-- ---------------------------------------------------------------------------

COMMENT ON VIEW evo.active_messages IS 'Visão pass-through de evolution_messages filtrando mensagens ativas (sem estado final), usada para consultas de mensagens em andamento.';

COMMENT ON VIEW evo.active_webhook_events IS 'Visão que normaliza eventos de webhook v2 e expõe apenas eventos ativos/pendentes de processamento, com status derivado do payload original.';

COMMENT ON VIEW evo.evolution_messages_v2 IS 'Visão pass-through de evolution_messages no formato v2, padronizando nomes e tipos para os consumidores atuais. ARMADILHA: mudanças de contrato devem ser feitas na view, não na tabela base.';

COMMENT ON VIEW evo.v_ack_loss_candidates IS 'Monitoramento: candidatos a perda de ACK (mensagens sem confirmação de entrega dentro da janela esperada), auxiliando diagnóstico de delivery do WhatsApp.';

COMMENT ON VIEW evo.v_alert_dashboard IS 'Monitoramento: agrega alertas ativos do pipeline para dashboard, com severidade e janela de ocorrência; NULL quando não há alertas no período.';

COMMENT ON VIEW evo.v_bootstrap_history IS 'Monitoramento: histórico de inicializações do pipeline de ingestão, com timestamps e resultado de cada bootstrap.';

COMMENT ON VIEW evo.v_dedup_failures IS 'Monitoramento: registros de falha de deduplicação (duplicatas suspeitas ou conflito de chave); NULL = sem falhas registradas.';

COMMENT ON VIEW evo.v_evolution_pipeline_health IS 'Monitoramento: saúde geral do pipeline Evolution (ingestão, processamento e entrega), consolidando métricas de latência e erro.';

COMMENT ON VIEW evo.v_incident_metrics_48h IS 'Monitoramento: métricas de incidentes das últimas 48 horas (contagem, duração, impacto); janela fixa de 48h, NULL fora do período.';

COMMENT ON VIEW evo.v_ingest_reconciliation IS 'Monitoramento: reconciliação entre origem (webhook/Evolution) e destino (evolution_messages), apontando divergências de contagem ou estado.';

COMMENT ON VIEW evo.v_kpi_overview IS 'Monitoramento: visão consolidada de KPIs do pipeline (volumes, taxas de sucesso/falha, latências) para acompanhamento executivo.';

COMMENT ON VIEW evo.v_lid_convergence_status IS 'Monitoramento: status de convergência LID (JIDs de grupo normalizados para @lid), indicando JIDs ainda não convergidos.';

COMMENT ON VIEW evo.v_logpatch_health IS 'Monitoramento: saúde dos patches de log aplicados em runtime, com versão aplicada e pendências; NULL = sem patch pendente.';

COMMENT ON VIEW evo.v_messages_unified IS 'Visão unificada de mensagens consolidando evolution_messages e fontes derivadas em um único contrato de leitura, pass-through para compatibilidade.';

COMMENT ON VIEW evo.v_pipeline_health IS 'Monitoramento: saúde do pipeline de mensageria (stages de ingestão, processamento e entrega) com status por etapa.';

COMMENT ON VIEW evo.v_production_scorecard IS 'Monitoramento: scorecard de produção com indicadores de disponibilidade, qualidade e SLA do pipeline WhatsApp.';

COMMENT ON VIEW evo.v_security_audit IS 'Monitoramento: visão de auditoria de segurança (acessos, alterações sensíveis e tentativas negadas) para revisão periódica.';

COMMENT ON VIEW evo.v_spurious_close_events IS 'Monitoramento: eventos de fechamento espúrios (conexões fechadas sem causa aparente), usados para detectar instabilidade de conexão.';

COMMENT ON VIEW evo.v_unused_index_candidates IS 'Monitoramento: candidatos a índice não utilizado, apoiando decisões de remoção. ARMADILHA: validar com pg_stat_user_indexes antes de qualquer DROP.';

COMMENT ON VIEW evo.v_vps_go_live_checklist IS 'Monitoramento: checklist de go-live da VPS (requisitos de infraestrutura atendidos/pendentes); NULL = item não avaliado.';

COMMENT ON VIEW evo.v_vps_live_status IS 'Monitoramento: status ao vivo da VPS (containers, traefik e serviços críticos), fonte para dashboards de disponibilidade.';

COMMENT ON VIEW evo.v_wpp2_uptime_24h IS 'Monitoramento: uptime do canal WPP2 nas últimas 24h, com janelas de indisponibilidade e percentual de disponibilidade.';

-- ---------------------------------------------------------------------------
-- PARTE B — evolution_instance_credentials (CREDENCIAIS — tabela SENSÍVEL)
-- ---------------------------------------------------------------------------

COMMENT ON TABLE evo.evolution_instance_credentials IS 'Credenciais de acesso das instâncias WhatsApp da Evolution (apikey, URLs e identificação). Tabela SENSÍVEL: apikey referencia vault.secrets — nunca logar valores.';

COMMENT ON COLUMN evo.evolution_instance_credentials.id IS 'UUID público da credencial, chave primária.';

COMMENT ON COLUMN evo.evolution_instance_credentials.instance_name IS 'Nome da instância WhatsApp na Evolution, identificador amigável usado em chamadas de API.';

COMMENT ON COLUMN evo.evolution_instance_credentials.connection_id IS 'UUID da conexão da instância na Evolution (estado de conexão WebSocket). NULL = instância nunca conectada.';

COMMENT ON COLUMN evo.evolution_instance_credentials.apikey IS 'Chave de API da instância para autenticação na Evolution. ARMADILHA: pode estar em texto plano no banco — nunca logar, mascarar ou expor em exports; priorizar vault_secret_id.';

COMMENT ON COLUMN evo.evolution_instance_credentials.apikey_hash IS 'Hash (SHA-256) da apikey para comparação sem expor o valor em claro. NULL = apikey sem hash registrado.';

COMMENT ON COLUMN evo.evolution_instance_credentials.apikey_created_at IS 'Timestamp de criação/rotação da apikey. NULL = data desconhecida.';

COMMENT ON COLUMN evo.evolution_instance_credentials.vault_secret_id IS 'Referência ao secret correspondente no vault (vault.secrets), fonte preferencial da apikey. NULL = secret não provisionado.';

COMMENT ON COLUMN evo.evolution_instance_credentials.health_status IS 'Estado de saúde da instância (enum-like: healthy, degraded, down). NULL = ainda não avaliado.';

COMMENT ON COLUMN evo.evolution_instance_credentials.health_checked_at IS 'Timestamp da última checagem de saúde. NULL = nunca checado.';

COMMENT ON COLUMN evo.evolution_instance_credentials.created_at IS 'Timestamp de criação do registro.';

COMMENT ON COLUMN evo.evolution_instance_credentials.updated_at IS 'Timestamp da última atualização do registro. NULL = nunca atualizado após criação.';

COMMENT ON COLUMN evo.evolution_instance_credentials.base_url IS 'URL base da instância/API Evolution. NULL = não configurada.';

COMMENT ON COLUMN evo.evolution_instance_credentials.api_url IS 'URL completa da API da instância. NULL = não configurada.';

COMMENT ON COLUMN evo.evolution_instance_credentials.manager_url IS 'URL do manager (gerenciador de instâncias) da Evolution. NULL = não configurada.';

COMMENT ON COLUMN evo.evolution_instance_credentials.whatsapp_number IS 'Número WhatsApp vinculado à instância (formato E.164). NULL = número não informado.';

COMMENT ON COLUMN evo.evolution_instance_credentials.owner_name IS 'Nome do responsável/owner da instância. NULL = não informado.';

COMMENT ON COLUMN evo.evolution_instance_credentials.notes IS 'Observações livres sobre a credencial/instância. NULL = sem anotações.';

COMMENT ON COLUMN evo.evolution_instance_credentials.last_connection_state IS 'Último estado de conexão reportado pela Evolution (enum-like: open, close, connecting). NULL = sem estado registrado.';

-- ---------------------------------------------------------------------------
-- PARTE C — evolution_mirror_* (tabelas VAZIAS — plano de mirror R2)
-- ---------------------------------------------------------------------------

COMMENT ON TABLE evo.evolution_mirror_batches IS 'Lote de mirror para R2 (S3), agrupando arquivos a copiar com status e contadores. Tabela vazia — plano de mirror R2 ainda não ativo.';

COMMENT ON COLUMN evo.evolution_mirror_batches.id IS 'UUID do lote de mirror, chave primária.';

COMMENT ON COLUMN evo.evolution_mirror_batches.s3_key IS 'Chave (prefixo) S3/R2 do lote. NULL = não gerado.';

COMMENT ON COLUMN evo.evolution_mirror_batches.status IS 'Estado do lote (enum-like: pending, running, completed, failed). NULL = não iniciado.';

COMMENT ON COLUMN evo.evolution_mirror_batches.total_files IS 'Total de arquivos previstos no lote.';

COMMENT ON COLUMN evo.evolution_mirror_batches.processed_files IS 'Arquivos processados até o momento. NULL = nenhum processado.';

COMMENT ON COLUMN evo.evolution_mirror_batches.byte_count IS 'Tamanho total do lote em bytes.';

COMMENT ON COLUMN evo.evolution_mirror_batches.checksum IS 'Checksum do conteúdo do lote para validação de integridade. NULL = não calculado.';

COMMENT ON COLUMN evo.evolution_mirror_batches.source IS 'Origem dos dados (tabela/fonte do mirror). NULL = não informado.';

COMMENT ON COLUMN evo.evolution_mirror_batches.created_at IS 'Timestamp de criação do lote.';

COMMENT ON COLUMN evo.evolution_mirror_batches.updated_at IS 'Timestamp da última atualização do lote. NULL = nunca atualizado.';

COMMENT ON COLUMN evo.evolution_mirror_batches.started_at IS 'Timestamp de início do processamento. NULL = não iniciado.';

COMMENT ON COLUMN evo.evolution_mirror_batches.finished_at IS 'Timestamp de conclusão do lote. NULL = não concluído.';

COMMENT ON TABLE evo.evolution_mirror_checkpoints IS 'Checkpoints de progresso do mirror (último valor processado por chave) para retomada incremental. Tabela vazia — plano de mirror R2.';

COMMENT ON COLUMN evo.evolution_mirror_checkpoints.id IS 'UUID do checkpoint, chave primária.';

COMMENT ON COLUMN evo.evolution_mirror_checkpoints.checkpoint_key IS 'Chave lógica do checkpoint (ex.: tabela+coluna).';

COMMENT ON COLUMN evo.evolution_mirror_checkpoints.last_value IS 'Último valor processado (watermark) para retomada incremental. NULL = nenhum valor processado.';

COMMENT ON COLUMN evo.evolution_mirror_checkpoints.status IS 'Estado do checkpoint (enum-like: active, done, failed). NULL = não definido.';

COMMENT ON COLUMN evo.evolution_mirror_checkpoints.created_at IS 'Timestamp de criação do checkpoint.';

COMMENT ON COLUMN evo.evolution_mirror_checkpoints.updated_at IS 'Timestamp da última atualização do checkpoint. NULL = nunca atualizado.';

COMMENT ON TABLE evo.evolution_mirror_media_queue IS 'Fila de mídias pendentes de mirror para R2 (S3), com tentativas e erros. Tabela vazia — plano de mirror R2 ainda não ativo.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.id IS 'UUID do item da fila, chave primária.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.message_id IS 'UUID da mensagem de origem associada à mídia. NULL = mídia órfã.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.status IS 'Estado do item (enum-like: pending, processing, done, failed). NULL = não processado.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.attempts IS 'Número de tentativas de mirror do item.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.last_error IS 'Último erro ocorrido no mirror do item. NULL = sem erro.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.created_at IS 'Timestamp de enfileiramento do item.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.updated_at IS 'Timestamp da última atualização do item. NULL = nunca atualizado.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.processed_at IS 'Timestamp em que o item foi processado com sucesso. NULL = não processado.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.media_url IS 'URL original da mídia (fonte de download). NULL = não informada.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.storage_path IS 'Caminho de destino no storage (R2/S3). NULL = não definido.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.storage_bucket IS 'Bucket de destino no storage. NULL = não definido.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.file_size IS 'Tamanho do arquivo em bytes. NULL = desconhecido.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.sha256 IS 'Hash SHA-256 do arquivo para validação de integridade. NULL = não calculado.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.next_attempt_at IS 'Próxima janela de retry do item. NULL = pronto para processar.';

COMMENT ON COLUMN evo.evolution_mirror_media_queue.locked_at IS 'Timestamp de lock do item durante processamento (evita processamento concorrente). NULL = sem lock ativo.';

COMMENT ON TABLE evo.evolution_mirror_runs IS 'Registro de execuções (runs) do processo de mirror, com tipo, status e contadores. Tabela vazia — plano de mirror R2.';

COMMENT ON COLUMN evo.evolution_mirror_runs.id IS 'UUID da execução, chave primária.';

COMMENT ON COLUMN evo.evolution_mirror_runs.run_type IS 'Tipo da execução (enum-like: full, incremental, media, backfill).';

COMMENT ON COLUMN evo.evolution_mirror_runs.status IS 'Estado da execução (enum-like: running, completed, failed, cancelled). NULL = não iniciada.';

COMMENT ON COLUMN evo.evolution_mirror_runs.started_at IS 'Timestamp de início da execução. NULL = não iniciada.';

COMMENT ON COLUMN evo.evolution_mirror_runs.finished_at IS 'Timestamp de conclusão da execução. NULL = não concluída.';

COMMENT ON COLUMN evo.evolution_mirror_runs.source_table IS 'Tabela de origem do mirror. NULL = não informada.';

COMMENT ON COLUMN evo.evolution_mirror_runs.target IS 'Destino do mirror (ex.: bucket R2, schema alvo). NULL = não informado.';

COMMENT ON COLUMN evo.evolution_mirror_runs.rows_processed IS 'Linhas processadas na execução.';

COMMENT ON COLUMN evo.evolution_mirror_runs.rows_failed IS 'Linhas com falha na execução. NULL = nenhuma falha.';

COMMENT ON COLUMN evo.evolution_mirror_runs.error_message IS 'Mensagem de erro da execução (quando falhou). NULL = sem erro.';

COMMENT ON COLUMN evo.evolution_mirror_runs.metadata IS 'Metadados livres da execução em JSONB (parâmetros e contexto). NULL = sem metadados.';

COMMENT ON COLUMN evo.evolution_mirror_runs.created_at IS 'Timestamp de criação do registro da execução.';

COMMENT ON COLUMN evo.evolution_mirror_runs.updated_at IS 'Timestamp da última atualização do registro. NULL = nunca atualizado.';

COMMENT ON COLUMN evo.evolution_mirror_runs.triggered_by IS 'Quem/o que disparou a execução (ex.: cron, manual, API). NULL = não informado.';

-- ---------------------------------------------------------------------------
-- PARTE D — Colunas restantes
-- ---------------------------------------------------------------------------

COMMENT ON COLUMN evo.evolution_messages_wpp2.remote_jid_original IS 'JID original recebido do webhook, antes do trigger trg_normalize_remote_jid. NULL = sem alteração.';
-- AGENTE-99 complemento final (gerado pelo orquestrador) — colunas/tabelas/funcoes restantes
COMMENT ON COLUMN evo.evolution_messages.id IS 'PK interna uuid, gerado pelo banco. Use para JOINs internos. NÃO é o ID do WhatsApp.';
COMMENT ON COLUMN evo.evolution_messages.message_id IS 'ID da mensagem gerado pelo WhatsApp/Baileys. Junto com instance_name forma a chave única de negócio (UNIQUE uq_msg_msgid_instance).';
COMMENT ON COLUMN evo.evolution_messages.remote_jid IS 'JID do contato remoto ("PHONE@s.whatsapp.net" ou "GROUP@g.us"). ARMADILHA: pode conter "@lid" — trigger fn_normalize_remote_jid resolve via lid_phone_map.';
COMMENT ON COLUMN evo.evolution_messages.from_me IS 'true = mensagem enviada pela Promo Brindes (outbound). false = recebida (inbound).';
COMMENT ON COLUMN evo.evolution_messages.message_type IS 'Tipo canônico: text | image | audio | video | document | sticker | location | contact | poll | reaction | ptv | system | unknown.';
COMMENT ON COLUMN evo.evolution_messages.content IS 'Conteúdo de texto da mensagem. Para mídias: vazio ou caption. Truncado em 65535 chars.';
COMMENT ON COLUMN evo.evolution_messages.media_url IS 'URL pública da mídia (storage próprio ou CDN WhatsApp — CDN expira em 7 dias). NULL = texto ou mídia perdida.';
COMMENT ON COLUMN evo.evolution_messages.media_mimetype IS 'MIME type do arquivo (ex.: audio/ogg; codecs=opus). NULL para texto.';
COMMENT ON COLUMN evo.evolution_messages.quoted_message_id IS 'message_id da mensagem citada (reply). NULL = sem reply.';
COMMENT ON COLUMN evo.evolution_messages.is_starred IS 'true = marcada como estrela pelo agente no CRM.';
COMMENT ON COLUMN evo.evolution_messages.is_important IS 'true = marcada como importante pelo agente.';
COMMENT ON COLUMN evo.evolution_messages.category IS 'Categoria de negócio (pedido, reclamação, financeiro...). NULL = não categorizada.';
COMMENT ON COLUMN evo.evolution_messages.sentiment IS 'Sentimento por IA (positivo|neutro|negativo). NULL = não analisado.';
COMMENT ON COLUMN evo.evolution_messages.tags IS 'Array de tags livres.';
COMMENT ON COLUMN evo.evolution_messages.notes IS 'Notas internas do agente. NULL = sem nota.';
COMMENT ON COLUMN evo.evolution_messages.follow_up_at IS 'Timestamp agendado para follow-up. NULL = sem follow-up.';
COMMENT ON COLUMN evo.evolution_messages.follow_up_done IS 'true = follow-up executado.';
COMMENT ON COLUMN evo.evolution_messages.payload IS 'jsonb com payload resumido do webhook. Preenchimento histórico inconsistente.';
COMMENT ON COLUMN evo.evolution_messages.created_at IS 'Timestamp da mensagem (horário do evento, não do INSERT). SEMPRE filtrar por esta coluna.';
COMMENT ON COLUMN evo.evolution_messages.contact_id IS 'FK → evo.evolution_contacts.id. NULL em mensagens antigas/de contatos deletados.';
COMMENT ON COLUMN evo.evolution_messages.conversation_id IS 'FK → evo.evolution_conversations.id (partição conforme instance). NULL = conversa não vinculada.';
COMMENT ON COLUMN evo.evolution_messages.direction IS 'Direção canônica: inbound (contato→Promo) | outbound (Promo→contato). Garantido por trg_enforce_direction.';
COMMENT ON COLUMN evo.evolution_messages.status IS 'Status de entrega. ARMADILHA: dois formatos — UPPERCASE do webhook (READ, DELIVERY_ACK...) e lowercase do consumer (read, delivered, sent, failed).';
COMMENT ON COLUMN evo.evolution_messages.status_at IS 'Timestamp do último evento de status.';
COMMENT ON COLUMN evo.evolution_messages.caption IS 'Legenda de mídia. Separada de content.';
COMMENT ON COLUMN evo.evolution_messages.media_filename IS 'Nome original do arquivo (docs: ''Orçamento - 107753.pdf'').';
COMMENT ON COLUMN evo.evolution_messages.media_size IS 'Tamanho do arquivo em bytes. NULL quando não informado.';
COMMENT ON COLUMN evo.evolution_messages.sent_by_bot IS 'true = enviada por chatbot/automação.';
COMMENT ON COLUMN evo.evolution_messages.template_name IS 'Nome do template HSM aprovado pela Meta. NULL = mensagem ad-hoc.';
COMMENT ON COLUMN evo.evolution_messages.instance_name IS 'Nome da instância WhatsApp. Compõe a chave (message_id, instance_name).';
COMMENT ON COLUMN evo.evolution_messages.push_name IS 'Nome de exibição do remetente no momento do envio.';
COMMENT ON COLUMN evo.evolution_messages.media_type IS 'Tipo de mídia simplificado: image|audio|video|document|sticker.';
COMMENT ON COLUMN evo.evolution_messages.raw_data IS 'jsonb com payload completo do webhook (LGPD: dados brutos). Preenchimento variável.';
COMMENT ON COLUMN evo.evolution_messages.deleted_at IS 'Soft-delete. NULL = ativa.';
COMMENT ON COLUMN evo.evolution_messages.edited_at IS 'Timestamp da última edição pelo remetente. NULL = nunca editada.';
COMMENT ON COLUMN evo.evolution_messages.updated_at IS 'Timestamp do último UPDATE (trigger update_messages_updated_at).';
COMMENT ON COLUMN evo.evolution_messages.media_meta IS 'LEGADO: metadados do webhook original. Substituído por ingest_meta (2026-07).';
COMMENT ON COLUMN evo.evolution_messages.is_read IS 'true = lida pelo agente no CRM. Independente do status do WhatsApp.';
COMMENT ON COLUMN evo.evolution_messages.reply_to_id IS 'UUID interno (id) da mensagem citada. Resolvido por cron.';
COMMENT ON COLUMN evo.evolution_messages.media_bucket IS 'Bucket do storage: whatsapp-media | audio-messages | stickers. NULL = não baixado.';
COMMENT ON COLUMN evo.evolution_messages.media_path IS 'Caminho do objeto no bucket. NULL = não baixado.';
COMMENT ON COLUMN evo.evolution_messages.media_sha256 IS 'SHA-256 do binário (hex). NULL = não calculado.';
COMMENT ON COLUMN evo.evolution_messages.media_status IS 'pending|processing|ready|failed|expired|unknown|permanently_lost. Para mídias disponíveis: WHERE media_status = ''ready''.';
COMMENT ON COLUMN evo.evolution_messages.transcription_status IS 'pending|processing|done|failed|skipped. Feature não ativada (0 linhas).';
COMMENT ON COLUMN evo.evolution_messages.transcription IS 'Transcrição de áudio (Groq Whisper). NULL = não transcrito.';
COMMENT ON COLUMN evo.evolution_messages.error_code IS 'Código de erro quando status=''failed'' (ex.: not-acceptable).';
COMMENT ON COLUMN evo.evolution_messages.error_reason IS 'Descrição do erro, truncada em 200 chars.';
COMMENT ON COLUMN evo.evolution_messages.retry_attempt IS 'Número da tentativa atual de reenvio. NULL = nunca entrou em retry.';
COMMENT ON COLUMN evo.evolution_messages.retry_total IS 'Limite de tentativas de reenvio. NULL = não entrou em retry.';
COMMENT ON TABLE evo.evolution_messages IS 'Tabela-MÃE PARTICIONADA das mensagens do WhatsApp (dados vivem nas partições — ex.: evolution_messages_wpp2). Parent tem 0 linhas; SEMPRE consultar a partição correta. Comentários de colunas espelham a partição wpp2.';
COMMENT ON COLUMN evo.evolution_conversations.id IS 'PK uuid interno. Use para JOINs. Não é ID do WhatsApp.';
COMMENT ON COLUMN evo.evolution_conversations.contact_id IS 'FK → evo.evolution_contacts.id. Chave de JOIN para dados do contato.';
COMMENT ON COLUMN evo.evolution_conversations.remote_jid IS 'JID do contato ("PHONE@s.whatsapp.net"). UNIQUE com instance_name.';
COMMENT ON COLUMN evo.evolution_conversations.status IS 'Estado: aberta | arquivada (CHECK, valores em português). Filtro padrão: WHERE status = ''aberta''.';
COMMENT ON COLUMN evo.evolution_conversations.assigned_to IS 'UUID (text) do agente responsável → zapp.profiles.id.';
COMMENT ON COLUMN evo.evolution_conversations.department IS 'Departamento: comercial|financeiro|logistica|compras. 100% NULL na prática (2026-08).';
COMMENT ON COLUMN evo.evolution_conversations.subject IS 'Assunto definido pelo agente. NULL = sem assunto.';
COMMENT ON COLUMN evo.evolution_conversations.priority IS 'Prioridade: low|normal|high|urgent.';
COMMENT ON COLUMN evo.evolution_conversations.labels IS 'Array de labels da conversa (tags visuais no CRM).';
COMMENT ON COLUMN evo.evolution_conversations.message_count IS 'Total de mensagens na conversa (qualquer direção). Mantido por trigger/cron.';
COMMENT ON COLUMN evo.evolution_conversations.first_message_at IS 'Timestamp da primeira mensagem.';
COMMENT ON COLUMN evo.evolution_conversations.last_message_at IS 'Timestamp da última mensagem. Desnormalização para evitar JOIN.';
COMMENT ON COLUMN evo.evolution_conversations.last_inbound_at IS 'Última mensagem recebida (from_me=false). Para SLA de resposta.';
COMMENT ON COLUMN evo.evolution_conversations.last_outbound_at IS 'Última mensagem enviada pela Promo.';
COMMENT ON COLUMN evo.evolution_conversations.first_response_at IS 'Primeira resposta da Promo. Usado para first_response_seconds.';
COMMENT ON COLUMN evo.evolution_conversations.first_response_seconds IS 'SLA de primeira resposta (s). NULL = ainda não respondida.';
COMMENT ON COLUMN evo.evolution_conversations.resolution_at IS 'Quando foi marcada resolvida (status → ''arquivada''). NULL = aberta.';
COMMENT ON COLUMN evo.evolution_conversations.resolution_seconds IS 'Tempo de resolução (s): first_message_at → resolution_at.';
COMMENT ON COLUMN evo.evolution_conversations.is_bot_active IS 'true = chatbot gerenciando. Agentes devem verificar antes de intervir.';
COMMENT ON COLUMN evo.evolution_conversations.bot_session_id IS 'ID da sessão do chatbot. NULL = bot inativo.';
COMMENT ON COLUMN evo.evolution_conversations.satisfaction_score IS 'CSAT 1-5. NULL = não coletado.';
COMMENT ON COLUMN evo.evolution_conversations.satisfaction_comment IS 'Comentário do CSAT. NULL = não coletado.';
COMMENT ON COLUMN evo.evolution_conversations.instance_name IS 'Instância WhatsApp. Compõe a chave natural (remote_jid, instance_name).';
COMMENT ON COLUMN evo.evolution_conversations.metadata IS 'jsonb livre (Bitrix24, campanha...). 100% NULL (2026-08).';
COMMENT ON COLUMN evo.evolution_conversations.created_at IS 'Timestamp de criação.';
COMMENT ON COLUMN evo.evolution_conversations.updated_at IS 'Timestamp do último UPDATE (trigger).';
COMMENT ON COLUMN evo.evolution_conversations.last_message_content IS 'Preview da última mensagem (truncado). Desnormalização.';
COMMENT ON COLUMN evo.evolution_conversations.last_message_type IS 'Tipo da última mensagem. Desnormalização.';
COMMENT ON COLUMN evo.evolution_conversations.unread_count IS 'Mensagens inbound não lidas pelo agente. Decrementado ao abrir a conversa.';
COMMENT ON TABLE evo.evolution_conversations IS 'Tabela-MÃE PARTICIONADA das conversas (dados em partições por instância/departamento — ex.: evolution_conversations_wpp2). Parent tem 0 linhas; consultar a partição correta.';
COMMENT ON COLUMN evo.media_download_queue.id IS 'PK bigserial.';
COMMENT ON COLUMN evo.media_download_queue.message_id IS 'ID WhatsApp da mensagem dona da mídia.';
COMMENT ON COLUMN evo.media_download_queue.message_uuid IS 'UUID interno (evolution_messages_wpp2.id) da mensagem.';
COMMENT ON COLUMN evo.media_download_queue.remote_jid IS 'JID do contato.';
COMMENT ON COLUMN evo.media_download_queue.instance_name IS 'Instância WhatsApp.';
COMMENT ON COLUMN evo.media_download_queue.media_type IS 'Tipo: image|audio|video|document|sticker.';
COMMENT ON COLUMN evo.media_download_queue.media_key IS 'MediaKey do WhatsApp (necessário p/ download via Evolution API).';
COMMENT ON COLUMN evo.media_download_queue.direct_path IS 'DirectPath do WhatsApp para download.';
COMMENT ON COLUMN evo.media_download_queue.mimetype IS 'MIME type informado. Pode ser NULL — usar messages.media_mimetype se precisar.';
COMMENT ON COLUMN evo.media_download_queue.file_length IS 'Tamanho em bytes (do payload).';
COMMENT ON COLUMN evo.media_download_queue.status IS 'Estado da fila: pending|processing|ready|failed|expired (CHECK media_download_queue_status_check).';
COMMENT ON COLUMN evo.media_download_queue.download_url IS 'URL gerada para download.';
COMMENT ON COLUMN evo.media_download_queue.storage_path IS 'Caminho de destino no storage.';
COMMENT ON COLUMN evo.media_download_queue.retry_count IS 'Tentativas realizadas.';
COMMENT ON COLUMN evo.media_download_queue.max_retries IS 'Limite de tentativas.';
COMMENT ON COLUMN evo.media_download_queue.error_message IS 'Erro do último download. NULL = sem erro.';
COMMENT ON COLUMN evo.media_download_queue.priority IS 'Prioridade (maior = antes).';
COMMENT ON COLUMN evo.media_download_queue.created_at IS 'Timestamp de criação.';
COMMENT ON COLUMN evo.media_download_queue.processed_at IS 'Processado em. NULL = pendente.';
COMMENT ON COLUMN evo.media_download_queue.scan_result IS 'Resultado do scan de segurança: clean|blocked|pending.';
COMMENT ON COLUMN evo.media_download_queue.scanned_at IS 'Scan realizado em. NULL = não escaneado.';
COMMENT ON COLUMN evo.media_download_queue.next_retry_at IS 'Próxima tentativa (índice parcial de pending/retry).';
COMMENT ON COLUMN evo.media_download_queue.jitter_ms IS 'Jitter aleatório aplicado ao retry (anti-thundering herd).';
